?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftar SK PPKH | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Dokumen PPKH</p><h1>Daftar SK PPKH</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah SK PPKH</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" class="vstack gap-2"><input class="form-control" name="nomor_sk_ppkh" placeholder="Nomor SK PPKH" required><input type="date" class="form-control" name="tanggal_penerbitan" required value="<?=date('Y-m-d')?>"><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><input class="form-control" name="nomor_ippkh" placeholder="Nomor IPPKH"><input type="number" step="0.01" class="form-control" name="luas_kawasan" placeholder="Luas kawasan"><input class="form-control" name="lokasi" placeholder="Lokasi"><select class="form-select" name="status"><option>Aktif</option><option>Dicabut</option></select><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nomor SK</th><th>Tanggal</th><th>Perusahaan</th><th>IPPKH</th><th>Status</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT * FROM sk_ppkh ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_sk_ppkh'])?></td><td>